import{_ as o,o as a,c as e,a2 as r}from"./chunks/framework.DGvnA5EY.js";const c=JSON.parse('{"title":"本篇导读 · 附录","description":"> 内容来源：WorkBuddy 官方指南（非官方整理，© 本指南作者，保留所有权利） 正文四篇读完之后，你手上其实已经有两样东西：一堆散在各章里的提示词，和一堆看不懂就跳过去的术语。附录就是把它们收拾干净。","frontmatter":{"title":"本篇导读 · 附录"},"headers":[],"relativePath":"bluebook/附录/index.md","filePath":"bluebook/附录/index.md","lastUpdated":1792135267000}'),d={name:"bluebook/附录/index.md"};function l(i,t,n,s,u,h){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="本篇导读-·-附录" tabindex="-1">本篇导读 · 附录 <a class="header-anchor" href="#本篇导读-·-附录" aria-label="Permalink to &quot;本篇导读 · 附录&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南（非官方整理，© 本指南作者，保留所有权利）</p></blockquote><p>正文四篇读完之后，你手上其实已经有两样东西：<strong>一堆散在各章里的提示词</strong>，和<strong>一堆看不懂就跳过去的术语</strong>。附录就是把它们收拾干净。</p><h2 id="附录里有什么" tabindex="-1">附录里有什么 <a class="header-anchor" href="#附录里有什么" aria-label="Permalink to &quot;附录里有什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>附录</th><th>解决什么问题</th><th>什么时候翻</th></tr></thead><tbody><tr><td><a href="/workbuddy-guide/bluebook/附录/附录 A 常用指令模板/">附录 A · 常用指令模板</a></td><td>10 条通用骨架提示词，能套到任何任务</td><td>不知道该怎么跟 AI 说话时</td></tr><tr><td><a href="/workbuddy-guide/bluebook/附录/附录 B 场景速查表/">附录 B · 场景速查表</a></td><td>&quot;我要干 X → 用什么 → 看第几章&quot; 三种索引</td><td>记不清某个功能在哪章时</td></tr><tr><td><a href="/workbuddy-guide/bluebook/附录/附录 C 小白说明书速查表/">附录 C · 小白说明书速查表</a></td><td>全篇术语按主题汇成字典，可检索</td><td>遇到看不懂的词时</td></tr></tbody></table><h2 id="建议的用法" tabindex="-1">建议的用法 <a class="header-anchor" href="#建议的用法" aria-label="Permalink to &quot;建议的用法&quot;">​</a></h2><p><strong>这三个附录不是用来&quot;读&quot;的，是用来&quot;查&quot;的。</strong> 顺序应该是：</p><ol><li><strong>先按需查</strong>——卡住了来查，别通读。</li><li><strong>提示词抄进剪贴板</strong>——附录 A 每条都可以直接复制。把用得上的 2–3 条存成自己的模板。</li><li><strong>术语表定期扫</strong>——附录 C 每天扫两条，一个月你就把 AI 的黑话认全了。</li></ol><h2 id="一个提醒" tabindex="-1">一个提醒 <a class="header-anchor" href="#一个提醒" aria-label="Permalink to &quot;一个提醒&quot;">​</a></h2><p>附录 A 里的模板都是<strong>通用骨架</strong>，它们能保证你不跑偏，但不能替你省掉&quot;想清楚要什么&quot;这一步。</p><p><strong>AI 的能力上限，取决于你能说清到什么程度。</strong> 模板是脚手架，不是替代思考。</p><h2 id="本附录任务清单" tabindex="-1">本附录任务清单 <a class="header-anchor" href="#本附录任务清单" aria-label="Permalink to &quot;本附录任务清单&quot;">​</a></h2><ul><li>[ ] 打开附录 A，把「五问定标」抄进剪贴板用一次</li><li>[ ] 打开附录 B，找到你今天最想解决的那件事对应的章节</li><li>[ ] 打开附录 C，搜一个你一直搞不懂的词</li><li>[ ] 收藏这三页，下次卡住先来搜而不是重新翻 28 章</li></ul><hr><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>',15)])])}const p=o(d,[["render",l]]);export{c as __pageData,p as default};
